import{J as e,n as t,ot as n,q as r}from"./chunks/framework.1lTNTJZP.js";var i=JSON.parse(`{"title":"Class: NetherNetIdentity","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: NetherNetIdentity"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/nethernet/classes/NetherNetIdentity"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/nethernet/classes/NetherNetIdentity"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/nethernet/src"}},"headers":[],"relativePath":"api/@jsprismarine/nethernet/classes/NetherNetIdentity.md","filePath":"api/@jsprismarine/nethernet/classes/NetherNetIdentity.md","lastUpdated":1794343625000}`),a={name:`api/@jsprismarine/nethernet/classes/NetherNetIdentity.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/nethernet</a> / NetherNetIdentity</p><h1 id="class-nethernetidentity" tabindex="-1">Class: NetherNetIdentity <a class="header-anchor" href="#class-nethernetidentity" aria-label="Permalink to “Class: NetherNetIdentity”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/89ecd7aa44a218fdbd7b913dbf13939a7537d3e1/packages/nethernet/src/NetherNetIdentity.ts#L55" target="_blank" rel="noreferrer">NetherNetIdentity.ts:55</a></p><p>A NetherNet identity: a P-384 key whose public half a session description carries, signed, in <code>a=identity</code>. A client refuses an answer without one, and Bedrock Dedicated Server refuses an offer without one.</p><p>A server&#39;s key must survive restarts: over plain HTTP the client remembers it the first time and asks the player about any other. <a href="#loadorcreate">NetherNetIdentity.loadOrCreate</a> keeps it in a file.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new NetherNetIdentity</strong>(<code>privateKey</code>, <code>options?</code>): <code>NetherNetIdentity</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/89ecd7aa44a218fdbd7b913dbf13939a7537d3e1/packages/nethernet/src/NetherNetIdentity.ts#L66" target="_blank" rel="noreferrer">NetherNetIdentity.ts:66</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="privatekey" tabindex="-1">privateKey <a class="header-anchor" href="#privatekey" aria-label="Permalink to “privateKey”">​</a></h5><p><code>KeyObject</code></p><p>A P-384 private key.</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#nethernetidentityoptions"><code>NetherNetIdentityOptions</code></a> = <code>{}</code></p><p>How the identity presents itself; a server&#39;s by default.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>NetherNetIdentity</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="sign" tabindex="-1">sign() <a class="header-anchor" href="#sign" aria-label="Permalink to “sign()”">​</a></h3><blockquote><p><strong>sign</strong>(<code>description</code>): <code>Promise</code>&lt;<code>string</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/89ecd7aa44a218fdbd7b913dbf13939a7537d3e1/packages/nethernet/src/NetherNetIdentity.ts#L109" target="_blank" rel="noreferrer">NetherNetIdentity.ts:109</a></p><p>The description with <code>a=identity</code> added: a self-signed token carrying the public key as <code>cpk</code>, and a detached signature over the description&#39;s DTLS fingerprints, which binds the key to the certificate WebRTC will present.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="description" tabindex="-1">description <a class="header-anchor" href="#description" aria-label="Permalink to “description”">​</a></h5><p><code>string</code></p><p>The SDP offer or answer, with its <code>a=fingerprint</code> lines.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code>&gt;</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the description has no fingerprint to sign.</p><hr><h3 id="client" tabindex="-1">client() <a class="header-anchor" href="#client" aria-label="Permalink to “client()”">​</a></h3><blockquote><p><code>static</code> <strong>client</strong>(<code>domain?</code>): <code>NetherNetIdentity</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/89ecd7aa44a218fdbd7b913dbf13939a7537d3e1/packages/nethernet/src/NetherNetIdentity.ts#L85" target="_blank" rel="noreferrer">NetherNetIdentity.ts:85</a></p><p>A fresh client identity, for one connection.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="domain" tabindex="-1">domain? <a class="header-anchor" href="#domain" aria-label="Permalink to “domain?”">​</a></h5><p><code>string</code> = <code>&#39;self&#39;</code></p><p>The identity provider&#39;s domain, as the client names it.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>NetherNetIdentity</code></p><hr><h3 id="loadorcreate" tabindex="-1">loadOrCreate() <a class="header-anchor" href="#loadorcreate" aria-label="Permalink to “loadOrCreate()”">​</a></h3><blockquote><p><code>static</code> <strong>loadOrCreate</strong>(<code>file</code>): <code>NetherNetIdentity</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/89ecd7aa44a218fdbd7b913dbf13939a7537d3e1/packages/nethernet/src/NetherNetIdentity.ts#L94" target="_blank" rel="noreferrer">NetherNetIdentity.ts:94</a></p><p>Reads the key from <code>file</code>, or makes one and writes it there, readable by its owner only.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="file" tabindex="-1">file <a class="header-anchor" href="#file" aria-label="Permalink to “file”">​</a></h5><p><code>string</code></p><p>Where the PKCS #8 PEM key lives.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>NetherNetIdentity</code></p>`,53)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};